   879  {
   880      SOCKET_PROBE(WRITE, sock, bufs, bufcnt, cb);
   881
   882      assert(sock->_cb.write == NULL);
   883      sock->_cb.write = cb;
   884
   885      for (size_t i = 0; i != bufcnt; ++i) {
   886          sock->bytes_written += bufs[i].len;
   887  #if H2O_SOCKET_DUMP_WRITE
   888          h2o_error_printf("writing %zu bytes to fd:%d\n", bufs[i].len, h2o_socket_get_fd(sock));
   889          h2o_dump_memory(stderr, bufs[i].base, bufs[i].len);
   890  #endif
   891      }
   892
   893      do_write(sock, bufs, bufcnt);
   894  }
