   126  /**
   127   * Callbacks of `h2o_sendvec_t`. Random access capability has been removed. `read_` and `send_` only provide one-pass sequential
   128   * access. Properties of `h2o_sendvec_t` (e.g., `len`, `raw`) are adjusted as bytes are read / sent from the vector.
   129   */
   130  typedef struct st_h2o_sendvec_callbacks_t {
   131      /**
   132       * Mandatory callback used to load the bytes held by the vector. Returns if the operation succeeded. When false is returned, the
   133       * generator is considered as been error-closed by itself.  If the callback is `h2o_sendvec_read_raw`, the data is available as
   134       * raw bytes in `h2o_sendvec_t::raw`.
   135       */
   136      int (*read_)(h2o_sendvec_t *vec, void *dst, size_t len);
   137      /**
   138       * Optional callback for sending contents of a vector directly to a socket. Returns number of bytes being sent (could be zero),
   139       * or, upon error, SIZE_MAX.
   140       */
   141      size_t (*send_)(h2o_sendvec_t *vec, int sockfd, size_t len);
   142  } h2o_sendvec_callbacks_t;
   143
   144  /**
   145   * send vector. Unlike an ordinary `h2o_iovec_t`, the vector has a callback that allows the sender to delay the flattening of data
   146   * until it becomes necessary.
   147   */
   148  struct st_h2o_sendvec_t {
   149      /**
   150       *
   151       */
   152      const h2o_sendvec_callbacks_t *callbacks;
   153      /**
   154       * size of the vector
   155       */
   156      size_t len;
   157      /**
   158       *
   159       */
   160      union {
   161          char *raw;
   162          uint64_t cb_arg[2];
   163      };
